import { z } from "zod";

/**
 * Narrow schemas for the parts of Codex's app-server protocol the chat
 * uses (Codex 0.167.1). Only the fields read are named; anything else is
 * dropped, and a message that does not fit is ignored or shown plainly,
 * never a crash. The full protocol is generated by
 * `codex app-server generate-ts`; it changes often, so it is not copied in.
 */

export function parsed<T>(schema: z.ZodType<T>, value: unknown): T | null {
	const result = schema.safeParse(value);
	return result.success ? result.data : null;
}

const Text = z.string();
const MaybeText = z.string().nullable().optional();

export const TurnError = z.object({
	message: z.string().optional(),
	codexErrorInfo: z.unknown().optional(),
});
export type TurnError = z.infer<typeof TurnError>;

export const Turn = z.object({
	id: z.string(),
	status: z.string(),
	error: TurnError.nullable().optional(),
	startedAt: z.number().nullable().optional(),
	completedAt: z.number().nullable().optional(),
	items: z.array(z.unknown()).optional(),
});
export type Turn = z.infer<typeof Turn>;

export const ThreadResult = z.object({
	thread: z.object({ id: z.string(), name: MaybeText }),
	model: z.string(),
	reasoningEffort: MaybeText,
	sandbox: z.unknown().optional(),
});
export type ThreadResult = z.infer<typeof ThreadResult>;

export const TurnStartResult = z.object({ turn: z.object({ id: z.string() }) });

export const TurnsList = z.object({
	data: z.array(Turn),
	nextCursor: MaybeText,
});

/** Every item has a type and an id; the rest depends on the type. */
export const ItemBase = z.object({ type: z.string(), id: z.string() });

export const UserMessageItem = z.object({
	content: z.array(
		z.object({
			type: z.string(),
			text: z.string().optional(),
			path: z.string().optional(),
		}),
	),
});

export const TextItem = z.object({ text: Text });

const CommandAction = z.object({
	type: z.string(),
	path: MaybeText,
	query: MaybeText,
});

export const CommandItem = z.object({
	command: Text,
	source: MaybeText,
	status: z.string(),
	commandActions: z.array(CommandAction).nullable().optional(),
	aggregatedOutput: MaybeText,
	exitCode: z.number().nullable().optional(),
});
export type CommandItem = z.infer<typeof CommandItem>;

export const FileChangeItem = z.object({
	changes: z.array(
		z.object({
			path: Text,
			kind: z.object({ type: z.string(), move_path: MaybeText }),
			diff: Text,
		}),
	),
	status: z.string(),
});
export type FileChangeItem = z.infer<typeof FileChangeItem>;

export const McpToolCallItem = z.object({
	server: Text,
	tool: Text,
	status: z.string(),
	arguments: z.unknown(),
	result: z
		.object({ content: z.array(z.unknown()) })
		.nullable()
		.optional(),
	error: z.object({ message: Text }).nullable().optional(),
});

export const DynamicToolCallItem = z.object({
	tool: Text,
	arguments: z.unknown(),
	status: z.string(),
	contentItems: z.array(z.unknown()).nullable().optional(),
	success: z.boolean().nullable().optional(),
});

export const CollabToolCallItem = z.object({
	tool: Text,
	status: z.string(),
	receiverThreadIds: z.array(z.string()),
	prompt: MaybeText,
});

export const SubAgentActivityItem = z.object({
	kind: z.string(),
	agentThreadId: z.string(),
});

export const WebSearchItem = z.object({ query: Text });
export const ImageViewItem = z.object({ path: Text });
export const ReviewItem = z.object({ review: Text });

export const ItemNotification = z.object({
	item: z.unknown(),
	threadId: z.string(),
	turnId: z.string().optional(),
});

export const DeltaNotification = z.object({
	threadId: z.string(),
	itemId: z.string(),
	delta: Text,
});

export const TurnNotification = z.object({ threadId: z.string(), turn: Turn });

export const TokenUsageNotification = z.object({
	threadId: z.string(),
	tokenUsage: z.object({
		last: z.object({ totalTokens: z.number() }),
		modelContextWindow: z.number().nullable().optional(),
	}),
});

export const NameNotification = z.object({
	threadId: z.string(),
	threadName: MaybeText,
});

export const PlanStep = z.object({ step: Text, status: z.string() });
export type PlanStep = z.infer<typeof PlanStep>;

export const PlanNotification = z.object({
	threadId: z.string(),
	turnId: z.string(),
	plan: z.array(PlanStep),
});

export const ErrorNotification = z.object({
	threadId: z.string(),
	turnId: z.string().optional(),
	willRetry: z.boolean(),
	error: TurnError,
});

export const McpStartupNotification = z.object({
	threadId: z.string().nullable().optional(),
	name: z.string(),
	status: z.string(),
});

export const ResolvedNotification = z.object({
	requestId: z.union([z.number(), z.string()]),
});

/** What every approval or question request names. */
const ItemRequest = z.object({
	threadId: z.string(),
	itemId: z.string(),
});

export const CommandApprovalRequest = ItemRequest.extend({
	availableDecisions: z.array(z.unknown()).nullable().optional(),
});

export const UserInputRequest = ItemRequest.extend({
	questions: z.array(
		z.object({
			id: z.string(),
			header: Text,
			question: Text,
			isSecret: z.boolean().optional(),
			options: z
				.array(z.object({ label: Text, description: Text.optional() }))
				.nullable()
				.optional(),
		}),
	),
});
export type UserInputRequest = z.infer<typeof UserInputRequest>;

export const ElicitationRequest = z.object({
	threadId: z.string(),
	serverName: z.string(),
	_meta: z
		.object({
			codex_approval_kind: z.string().optional(),
			tool_name: z.string().optional(),
			tool_params: z.unknown().optional(),
		})
		.nullable()
		.optional(),
});

export const ModelList = z.object({
	data: z.array(
		z.object({
			id: z.string(),
			displayName: Text,
			description: Text.nullable().optional(),
			hidden: z.boolean().optional(),
			supportedReasoningEfforts: z
				.array(z.object({ reasoningEffort: z.string() }))
				.optional(),
			defaultReasoningEffort: MaybeText,
			isDefault: z.boolean().optional(),
		}),
	),
});
export type ModelList = z.infer<typeof ModelList>;

export const SkillsList = z.object({
	data: z.array(
		z.object({
			skills: z.array(
				z.object({
					name: z.string(),
					description: Text.optional(),
					shortDescription: Text.optional(),
					interface: z.object({ shortDescription: MaybeText }).nullable().optional(),
					enabled: z.boolean(),
				}),
			),
		}),
	),
});

export type SkillsList = z.infer<typeof SkillsList>;

export const McpStatusList = z.object({
	data: z.array(
		z.object({
			name: z.string(),
			runtimeStatus: MaybeText,
			authStatus: MaybeText,
		}),
	),
	nextCursor: MaybeText,
});

/** `account/read`: only whether an account is signed in, never its email (ADR 0012). */
export const AccountRead = z.object({
	account: z.object({ type: z.string() }).nullable(),
	requiresOpenaiAuth: z.boolean(),
});
export type AccountRead = z.infer<typeof AccountRead>;

/** `account/updated`: a null auth mode means signed out. */
export const AccountUpdated = z.object({ authMode: z.string().nullable() });
